-- ---------------------------------------------------------------------------
-- LEAGUES
-- ---------------------------------------------------------------------------
-- Generated by scripts/seed/generate-tables.py --table leagues, transcribed from a seeded
-- database, not hand-typed. `legacy_name` carries the exact legacy `name` token -- 'UCL'/'EPL'
-- for the two leagues the app has always inserted under an abbreviation, name_en for the other
-- eight -- because the clubs roster INSERT further below still joins ON l.name = c.league_name
-- using those tokens. Writing name_en into `name` here would match nothing on a fresh database
-- and insert zero clubs.
CREATE TEMP TABLE seed_leagues (seed_key TEXT PRIMARY KEY, legacy_name TEXT, name_en TEXT, name_he TEXT, name_ru TEXT, logo_url TEXT, sort_order INTEGER, has_divisions BOOLEAN) ON COMMIT DROP;
