-- Adopt rows that predate seed_key, keyed on name_en. Not on the legacy `name` column: the
-- admin endpoints overwrite it with name_he on any save, and 3 of 10 production leagues already
-- carry a drifted one.
UPDATE leagues t SET seed_key = s.seed_key
FROM seed_leagues s
WHERE t.seed_key IS NULL AND t.name_en = s.name_en;

-- Refuse to insert a duplicate of a row that exists but could not be adopted. This is the
-- 2026-07-17 incident: a phantom 'UCL' row produced duplicate clubs and crashed init_db on
-- every pod boot. Failing loudly here is the better failure -- and the neutrality harness is
-- what stops it reaching production at all.
DO $$
DECLARE unadopted TEXT;
BEGIN
    SELECT string_agg(s.seed_key, ', ') INTO unadopted
    FROM seed_leagues s
    WHERE NOT EXISTS (SELECT 1 FROM leagues t WHERE t.seed_key = s.seed_key)
      AND EXISTS (SELECT 1 FROM leagues t
                  WHERE t.name_en = s.name_en OR t.name_he = s.name_he);
    IF unadopted IS NOT NULL THEN
        RAISE EXCEPTION 'seed.sql: leagues % exist but were not adopted; a name matches '
                        'while seed_key does not. Fix the adoption matcher -- inserting '
                        'would duplicate the row (2026-07-17 incident).', unadopted;
    END IF;
END $$;

-- `name` gets the LEGACY token, not name_en: the clubs roster below still joins
-- ON l.name = c.league_name using 'UCL'/'EPL'. Writing name_en here matches nothing on a
-- fresh database and inserts zero clubs. The UPDATE below deliberately never touches `name`,
-- so an adopted row keeps whatever production holds (Hebrew, on 3 of 10 rows).
INSERT INTO leagues (seed_key, name, name_en, name_he, name_ru, logo_url, sort_order, has_divisions)
SELECT s.seed_key, s.legacy_name, s.name_en, s.name_he, s.name_ru, s.logo_url,
       s.sort_order, s.has_divisions
FROM seed_leagues s
WHERE NOT EXISTS (SELECT 1 FROM leagues t WHERE t.seed_key = s.seed_key);

-- Admin-ownable columns yield to admin_edited; seed-owned ones are written unconditionally.
UPDATE leagues t SET
    name_en       = CASE WHEN 'name_en'  = ANY(t.admin_edited) THEN t.name_en  ELSE s.name_en  END,
    name_he       = CASE WHEN 'name_he'  = ANY(t.admin_edited) THEN t.name_he  ELSE s.name_he  END,
    name_ru       = CASE WHEN 'name_ru'  = ANY(t.admin_edited) THEN t.name_ru  ELSE s.name_ru  END,
    logo_url      = CASE WHEN 'logo_url' = ANY(t.admin_edited) THEN t.logo_url ELSE s.logo_url END,
    sort_order    = s.sort_order,
    has_divisions = s.has_divisions
FROM seed_leagues s
WHERE t.seed_key = s.seed_key;

-- ---------------------------------------------------------------------------
-- CLUBS
-- ---------------------------------------------------------------------------
-- Generated by scripts/seed/generate-tables.py --table clubs, transcribed from a seeded database,
-- not hand-typed -- 212 rows is exactly the kind of retyping that produces a silently wrong row.
-- Unlike leagues, clubs need no `legacy_name` column: the old roster INSERT wrote the English name
-- straight into the legacy `name` column (`SELECT l.id, c.name` where c.name is e.g. 'Real Madrid'),
-- identical to name_en, so writing name_en into `name` here for a newly-inserted club matches the
-- old behaviour exactly.
--
-- `league` and `also_in` resolve against leagues.seed_key (Task 4's temp table) -- a club playing
-- two competitions (e.g. Bayern Munich: uefa-champions-league + bundesliga) carries both, because
-- _VOTE_LEAGUES_TOUCHED_CTE in services/worker/rollups.py derives league scope from BOTH league_id
-- and domestic_league_id; losing either would silently under-count a multi-league ballot.
CREATE TEMP TABLE seed_clubs (seed_key TEXT PRIMARY KEY, league TEXT, also_in TEXT, name_en TEXT, name_he TEXT, name_ru TEXT, logo_url TEXT, group_label TEXT) ON COMMIT DROP;
